#!/usr/bin/env bash
# PostToolUse -> Write|Edit: type-check the edited file and report errors IN that file.
#   *.ts/*.tsx : project-local tsc from the nearest tsconfig.json. Plain config: `tsc --noEmit`. Solution config
#                (`"files": []` + references, as generated by Angular 21 CLI and create-vite): `tsc -p <ref> --noEmit`
#                per referenced config, or `tsc -b` when a reference is composite. tsc is found upwards (npm
#                workspaces hoist it); tsconfig errors, tsc crashes and a file outside every program are reported.
#   *.html     : inside an Angular workspace, a once-per-workspace notice that templates need `ng build`.
#   *.dart     : dart analyze <file>
#   *.py       : mypy or pyright, ONLY when the nearest pyproject.toml configures one
#                ([tool.mypy] / [tool.pyright]); otherwise silent (a deliberate project choice).
#
# Contract (see .claude/rules/hook-and-gate-authoring.md):
#   - Always exit 0 (advisory). Fails open when jq or the checker is missing.
#   - Each checker's OWN exit status is captured (`out=$(cmd); rc=$?`), never a pipe's.
#   - Output is built with `jq -n --arg`, so backslashes/quotes/tabs in compiler messages stay valid JSON.
#   - Delivered as PostToolUse additionalContext (stderr of an exit-0 hook is not shown to the model).
# Cost note: tsc and mypy check the whole project/import graph, so this can take seconds per edit.
# Test: bash .claude/hooks/post-edit-typecheck.sh --selftest
set -uo pipefail

MAX_LINES=5

nearest_up() { # $1 start dir, $2 file name -> echo dir containing it
  local d="$1"
  while [ -n "$d" ] && [ "$d" != "/" ]; do
    [ -f "$d/$2" ] && { printf '%s' "$d"; return 0; }
    d=$(dirname "$d")
  done
  return 1
}

once() { # $1 key -> succeeds the first time per key per TMPDIR (throttles repeated notices)
  local m="${TMPDIR:-/tmp}/cc-typecheck-$(printf '%s' "$1" | cksum | cut -d' ' -f1)"
  [ -e "$m" ] && return 1
  : > "$m" 2>/dev/null; return 0
}

ts_refs() { # $1 tsconfig.json -> referenced config paths, one per line (grep/sed: tsconfig is JSONC, jq rejects comments)
  local root ref
  root=$(dirname "$1")
  sed -n 's/.*"path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$1" | while IFS= read -r ref; do
    ref="$root/${ref#./}"
    [ -d "$ref" ] && ref="$ref/tsconfig.json"
    [ -f "$ref" ] && printf '%s\n' "$ref"
  done
}

check_ts() { # $1 file
  # Plain tsconfig (NestJS, libraries): `tsc --noEmit` at the nearest tsconfig.json, as before.
  # Solution tsconfig (`"files": []` + references: Angular 21 CLI, create-vite): the root program is EMPTY, so
  # `tsc --noEmit` there checks nothing and exits 0. Check each referenced config instead: `tsc -p <ref> --noEmit`
  # (Angular tsconfig.app/spec.json, Vite tsconfig.app/node.json); `tsc -b` when a reference is composite
  # (references between projects need their outputs built, exactly as the project's own build does).
  # Node/NestJS/MCP: tsc is often hoisted to an npm-workspaces root, so it is looked up from the tsconfig dir upwards.
  # `--listFiles` (non -b runs) proves the edited file is in a program: an `include` that misses it is not a pass.
  # Errors not tied to a source file (tsconfig errors, `error TS5083: Cannot read file`) and an exit code with no
  # diagnostics (crash) are surfaced; filtering them by file name would turn a broken config into silence.
  local file="$1" root rel out rc all="" lines ref refs tscdir tsc listed="" built=0 abs
  root=$(nearest_up "$(dirname "$file")" tsconfig.json) || return 0
  rel="${file#"$root"/}"
  if ! tscdir=$(nearest_up "$root" node_modules/.bin/tsc) || [ ! -x "$tscdir/node_modules/.bin/tsc" ]; then
    once "notsc:$root" && printf 'TypeScript: no tsc in node_modules/.bin of %s or any parent (run npm install); %s was NOT type-checked.' "$root" "$file"
    return 0
  fi
  tsc="$tscdir/node_modules/.bin/tsc"
  if ! grep -qE '"files"[[:space:]]*:[[:space:]]*\[[[:space:]]*\]' "$root/tsconfig.json"; then
    out=$(cd "$root" && "$tsc" --noEmit --pretty false --listFiles 2>&1); rc=$?
    listed="$out"
    [ "$rc" -ne 0 ] && all="$out"
  else
    refs=$(ts_refs "$root/tsconfig.json")
    if [ -z "$refs" ]; then
      printf 'TypeScript: %s/tsconfig.json is a solution config ("files": []) with no resolvable references; %s was NOT type-checked.' "$root" "$file"
      return 0
    fi
    if printf '%s\n' "$refs" | while IFS= read -r ref; do grep -qE '"composite"[[:space:]]*:[[:space:]]*true' "$ref" && exit 0; done; then
      out=$(cd "$root" && "$tsc" -b --pretty false 2>&1); rc=$?; built=1
      [ "$rc" -ne 0 ] && all="$out"
    else
      while IFS= read -r ref; do
        out=$(cd "$root" && "$tsc" -p "$ref" --noEmit --pretty false --listFiles 2>&1); rc=$?
        listed="$listed$out
"
        [ "$rc" -ne 0 ] && all="$all$out
"
      done <<EOF
$refs
EOF
    fi
  fi
  if [ -n "$all" ]; then
    local cfg msg=""
    lines=$(printf '%s\n' "$all" | grep -F "$rel(" | sort -u | head -"$MAX_LINES")
    cfg=$(printf '%s\n' "$all" | grep -E '^error TS|^[^(]*tsconfig[^(]*\.json\(' | sort -u | head -"$MAX_LINES")
    [ -n "$lines" ] && msg=$(printf 'TypeScript type errors in edited file %s:\n%s' "$file" "$lines")
    [ -n "$cfg" ] && msg="${msg:+$msg
}$(printf 'TypeScript: configuration errors in %s (%s was checked under a broken config):\n%s' "$root" "$file" "$cfg")"
    [ -n "$msg" ] && { printf '%s' "$msg"; return 0; }
    if ! grep -q 'error TS' <<EOF_ALL
$all
EOF_ALL
    then
      printf 'TypeScript: tsc exited without diagnostics in %s; %s was NOT type-checked:\n%s' "$root" "$file" "$(printf '%s\n' "$all" | grep -v '^/' | head -"$MAX_LINES")"
      return 0
    fi
  fi
  if [ "$built" -eq 0 ]; then # listFiles prints real paths (macOS /tmp -> /private/tmp): compare both spellings
    abs="$(cd "$(dirname "$file")" && pwd -P)/$(basename "$file")"
    if ! grep -qxF -e "$file" -e "$abs" <<EOF_LISTED
$listed
EOF_LISTED
    then
      once "notinprog:$file" && printf 'TypeScript: %s is not part of any program under %s (tsconfig include/exclude/files); it was NOT type-checked. Add it to a tsconfig or check it with its own config.' "$file" "$root"
    fi
  fi
  return 0
}

check_ng_template() { # $1 file: *.html inside an Angular workspace (tsc never sees templates)
  local root
  root=$(nearest_up "$(dirname "$1")" angular.json) || return 0
  once "ngtpl:$root" && printf 'Angular template %s is NOT type-checked by this hook: run `npx ng build` in %s (strictTemplates) before claiming it compiles.' "$1" "$root"
  return 0
}

check_dart() { # $1 file
  local file="$1" out lines
  command -v dart >/dev/null 2>&1 || return 0
  out=$(dart analyze "$file" 2>&1); : "$?"
  lines=$(printf '%s\n' "$out" | grep -E '^[[:space:]]*(error|warning)[[:space:]]+-' | head -"$MAX_LINES")
  [ -n "$lines" ] && printf 'Dart analysis issues in edited file %s:\n%s' "$file" "$lines"
  return 0
}

check_py() { # $1 file
  local file="$1" root out rc lines tool cmd=()
  root=$(nearest_up "$(dirname "$file")" pyproject.toml) || return 0
  if grep -qE '^\[tool\.mypy' "$root/pyproject.toml" 2>/dev/null; then tool=mypy
  elif grep -qE '^\[tool\.pyright' "$root/pyproject.toml" 2>/dev/null; then tool=pyright
  else return 0; fi
  if [ -x "$root/.venv/bin/$tool" ]; then cmd=("$root/.venv/bin/$tool")
  elif command -v "$tool" >/dev/null 2>&1; then cmd=("$tool")
  elif command -v uv >/dev/null 2>&1; then cmd=(uv run --no-sync "$tool")
  else
    printf 'Python type check: pyproject.toml configures %s but it was not found (PATH, .venv, uv); %s was NOT type-checked.' "$tool" "$file"
    return 0
  fi
  out=$(cd "$root" && "${cmd[@]}" "$file" 2>&1); rc=$?
  [ "$rc" -eq 0 ] && return 0
  lines=$(printf '%s\n' "$out" | grep -F "$(basename "$file")" | head -"$MAX_LINES")
  if [ -z "$lines" ] && [ "$rc" -ge 2 ]; then # crash / config error with no per-file line: surface it
    lines=$(printf '%s\n' "$out" | head -"$MAX_LINES")
    printf '%s could not run on %s (exit %s):\n%s' "$tool" "$file" "$rc" "$lines"
    return 0
  fi
  [ -n "$lines" ] && printf '%s errors in edited file %s:\n%s' "$tool" "$file" "$lines"
  return 0
}

run_hook() {
  local input file msg=""
  input=$(cat)
  command -v jq >/dev/null 2>&1 || return 0
  file=$(printf '%s' "$input" | jq -r '.tool_input.file_path // .tool_input.path // ""' 2>/dev/null) || file=""
  [ -n "$file" ] && [ -f "$file" ] || return 0
  case "$file" in
    *.ts|*.tsx|*.mts|*.cts) msg=$(check_ts "$file") ;;
    *.html) msg=$(check_ng_template "$file") ;;
    *.dart) msg=$(check_dart "$file") ;;
    *.py) msg=$(check_py "$file") ;;
  esac
  if [ -n "$msg" ]; then
    jq -n --arg m "$msg" '{hookSpecificOutput:{hookEventName:"PostToolUse",additionalContext:$m}}'
  fi
  return 0
}

selftest() {
  local self fail=0 tmp out bindir ts py nocfg
  self="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
  if bash -n "$self" 2>/dev/null; then echo "  ok   parses (bash -n)"; else echo "  FAIL does not parse"; return 1; fi
  command -v jq >/dev/null 2>&1 || { echo "  FAIL jq required"; return 1; }
  tmp=$(mktemp -d) || return 1
  bindir="$tmp/bin"; mkdir -p "$bindir"
  for t in jq cat head printf dirname basename grep sed pwd cksum cut sort node find; do
    p=$(command -v "$t" 2>/dev/null) && [ -x "$p" ] && ln -s "$p" "$bindir/$t"
  done
  run() { printf '{"tool_input":{"file_path":"%s"}}' "$1" | TMPDIR="$tmp" PATH="$2:$bindir" /bin/bash "$self" 2>/dev/null; }

  # --- TypeScript: fake local tsc that reports an error (with a backslash and quotation marks) and exits 2.
  ts="$tmp/ts"; mkdir -p "$ts/node_modules/.bin" "$ts/src"
  printf '{}' > "$ts/tsconfig.json"; printf 'export const a = 1;\n' > "$ts/src/a.ts"; printf 'export const b = 1;\n' > "$ts/src/b.ts"
  printf '#!/bin/sh\necho "src/a.ts(1,1): error TS2322: Type \\"x\\" C:\\\\dir not assignable"\necho "src/other.ts(2,2): error TS1: elsewhere"\nfor f in src/*.ts; do echo "$(pwd -P)/$f"; done\nexit 2\n' > "$ts/node_modules/.bin/tsc"
  chmod +x "$ts/node_modules/.bin/tsc"
  out=$(run "$ts/src/a.ts" "")
  if printf '%s' "$out" | jq -e '.hookSpecificOutput.additionalContext | contains("TS2322")' >/dev/null 2>&1; then
    echo "  ok   positive: tsc error in the edited file reported (valid JSON despite backslash and quotation marks)"; else echo "  FAIL ts positive (got: $out)"; fail=1; fi
  if printf '%s' "$out" | grep -q "elsewhere"; then echo "  FAIL errors from other files leaked"; fail=1; else echo "  ok   negative: errors in other files are not reported"; fi
  out=$(run "$ts/src/b.ts" "")
  if [ -z "$out" ]; then echo "  ok   negative: no error in the edited file is silent"; else echo "  FAIL ts negative (got: $out)"; fail=1; fi

  # --- Solution tsconfigs (Angular 21 CLI / create-vite shape). The fake tsc behaves like the real one: with no -p/-b
  # on a `"files": []` root the program is empty and it exits 0 (the old hook's vacuous green). With -p/-b, or on a
  # plain config, it reports every src file containing PLANTED. Set TYPECHECK_SELFTEST_TS=<node_modules/typescript>
  # to run the same fixtures with the real compiler.
  mkfixture() { # $1 dir, $2 kind: ng|vite|composite|plain
    local d="$1"; mkdir -p "$d/src/app" "$d/node_modules/.bin"
    case "$2" in
      ng) printf '{}\n' > "$d/angular.json"
          printf '/* JSONC comment */\n{\n  "compilerOptions": { "strict": true, "skipLibCheck": true, "target": "ES2022", "module": "preserve" },\n  "files": [],\n  "references": [\n    { "path": "./tsconfig.app.json" },\n    { "path": "./tsconfig.spec.json" }\n  ]\n}\n' > "$d/tsconfig.json"
          printf '{ "extends": "./tsconfig.json", "include": ["src/**/*.ts"], "exclude": ["src/**/*.spec.ts"] }\n' > "$d/tsconfig.app.json"
          printf '{ "extends": "./tsconfig.json", "include": ["src/**/*.spec.ts"] }\n' > "$d/tsconfig.spec.json"
          printf 'export const ok = 1;\n' > "$d/src/app/app.ts" ;;
      vite) printf '{\n  "files": [],\n  "references": [\n    { "path": "./tsconfig.app.json" },\n    { "path": "./tsconfig.node.json" }\n  ]\n}\n' > "$d/tsconfig.json"
          printf '{ "compilerOptions": { "strict": true, "noEmit": true, "jsx": "preserve", "module": "esnext", "moduleResolution": "bundler", "skipLibCheck": true }, "include": ["src"] }\n' > "$d/tsconfig.app.json"
          printf '{ "compilerOptions": { "strict": true, "noEmit": true, "skipLibCheck": true }, "include": ["vite.config.ts"] }\n' > "$d/tsconfig.node.json"
          printf 'export const v = 1;\n' > "$d/vite.config.ts"
          printf 'export const ok = 1;\n' > "$d/src/App.tsx" ;;
      composite) printf '{ "files": [], "references": [{ "path": "./tsconfig.lib.json" }] }\n' > "$d/tsconfig.json"
          printf '{ "compilerOptions": { "composite": true, "strict": true, "outDir": "out" }, "include": ["src/**/*.ts"] }\n' > "$d/tsconfig.lib.json"
          printf 'export const ok = 1;\n' > "$d/src/app/app.ts" ;;
      plain) printf '{ "compilerOptions": { "strict": true, "noEmit": true }, "include": ["src"] }\n' > "$d/tsconfig.json"
          printf 'export const ok = 1;\n' > "$d/src/app/app.ts" ;;
    esac
    if [ -n "${TYPECHECK_SELFTEST_TS:-}" ]; then
      ln -s "$TYPECHECK_SELFTEST_TS" "$d/node_modules/typescript"; ln -s ../typescript/bin/tsc "$d/node_modules/.bin/tsc"
    else
      cat > "$d/node_modules/.bin/tsc" <<'FAKE'
#!/bin/sh
mode=root; list=0
while [ $# -gt 0 ]; do case "$1" in -p) mode=project; shift ;; -b) mode=build ;; --listFiles) list=1 ;; esac; shift; done
if [ "$mode" = root ] && grep -qE '"files"[[:space:]]*:[[:space:]]*\[\]' tsconfig.json; then exit 0; fi
[ "$list" -eq 1 ] && find src vite.config.ts -name '*.ts*' 2>/dev/null | sed "s|^|$(pwd -P)/|"
hits=$(grep -rl PLANTED src vite.config.ts 2>/dev/null)
[ -z "$hits" ] && exit 0
for f in $hits; do echo "$f(1,14): error TS2322: Type 'string' is not assignable to type 'number'. [mode=$mode]"; done
exit 2
FAKE
      chmod +x "$d/node_modules/.bin/tsc"
    fi
  }
  plant() { printf 'export const PLANTED: number = "x";\n' >> "$1"; }
  for kind in ng vite; do
    mkfixture "$tmp/$kind" "$kind"
    f="$tmp/$kind/src/app/app.ts"; [ "$kind" = vite ] && f="$tmp/$kind/src/App.tsx"
    out=$(run "$f" "")
    if [ -z "$out" ]; then echo "  ok   negative: clean $kind project (solution tsconfig) is silent"; else echo "  FAIL clean $kind not silent (got: $out)"; fail=1; fi
    plant "$f"
    out=$(run "$f" "")
    if printf '%s' "$out" | jq -e '.hookSpecificOutput.additionalContext | contains("TS2322")' >/dev/null 2>&1; then
      echo "  ok   positive: planted error in $kind project (\"files\": [] + references) reported"; else echo "  FAIL $kind planted error missed (got: $out)"; fail=1; fi
    if [ -z "${TYPECHECK_SELFTEST_TS:-}" ]; then # mutation control: the pre-fix command (root `tsc --noEmit`) is vacuous here
      if (cd "$tmp/$kind" && node_modules/.bin/tsc --noEmit --pretty false >/dev/null 2>&1); then
        echo "  ok   mutation: root 'tsc --noEmit' (old hook) exits 0 on the planted $kind error"; else echo "  FAIL mutation control"; fail=1; fi
    fi
  done
  mkfixture "$tmp/comp" composite; plant "$tmp/comp/src/app/app.ts"
  out=$(run "$tmp/comp/src/app/app.ts" "")
  if printf '%s' "$out" | grep -q 'TS2322'; then echo "  ok   positive: composite reference checked (tsc -b)"; else echo "  FAIL composite (got: $out)"; fail=1; fi
  [ -z "${TYPECHECK_SELFTEST_TS:-}" ] && { printf '%s' "$out" | grep -q 'mode=build' || { echo "  FAIL composite did not use tsc -b"; fail=1; }; }
  mkfixture "$tmp/plain" plain; out=$(run "$tmp/plain/src/app/app.ts" "")
  if [ -z "$out" ]; then echo "  ok   negative: clean plain (NestJS-style) project silent"; else echo "  FAIL plain clean (got: $out)"; fail=1; fi
  plant "$tmp/plain/src/app/app.ts"; out=$(run "$tmp/plain/src/app/app.ts" "")
  if printf '%s' "$out" | grep -q 'TS2322'; then echo "  ok   positive: plain (NestJS-style) project still checked"; else echo "  FAIL plain planted (got: $out)"; fail=1; fi
  printf '<p>{{ x }}</p>\n' > "$tmp/ng/src/app/app.html"
  out=$(run "$tmp/ng/src/app/app.html" "")
  if printf '%s' "$out" | grep -q 'ng build'; then echo "  ok   positive: Angular template edit -> ng build notice"; else echo "  FAIL template notice (got: $out)"; fail=1; fi
  out=$(run "$tmp/ng/src/app/app.html" "")
  if [ -z "$out" ]; then echo "  ok   negative: template notice throttled (once per workspace)"; else echo "  FAIL template notice repeats"; fail=1; fi
  mkdir -p "$tmp/site"; printf '<p>x</p>\n' > "$tmp/site/index.html"; out=$(run "$tmp/site/index.html" "")
  if [ -z "$out" ]; then echo "  ok   negative: non-Angular .html silent"; else echo "  FAIL non-Angular html (got: $out)"; fail=1; fi
  rm -f "$tmp/vite/node_modules/.bin/tsc" "$tmp/vite/node_modules/typescript"
  out=$(run "$tmp/vite/src/App.tsx" "")
  if printf '%s' "$out" | grep -q 'NOT type-checked'; then echo "  ok   fail-open: missing tsc reported (no block, exit 0)"; else echo "  FAIL missing tsc hidden (got: $out)"; fail=1; fi

  # --- Node/NestJS/MCP shapes: hoisted tsc (npm workspaces), file outside every program, config error, crash.
  mkfixture "$tmp/ws/packages/api" plain; mkdir -p "$tmp/ws/node_modules"
  mv "$tmp/ws/packages/api/node_modules/.bin" "$tmp/ws/node_modules/.bin"
  [ -n "${TYPECHECK_SELFTEST_TS:-}" ] && { rm -f "$tmp/ws/packages/api/node_modules/typescript"; ln -s "$TYPECHECK_SELFTEST_TS" "$tmp/ws/node_modules/typescript"; }
  plant "$tmp/ws/packages/api/src/app/app.ts"; out=$(run "$tmp/ws/packages/api/src/app/app.ts" "")
  if printf '%s' "$out" | grep -q 'TS2322'; then echo "  ok   positive: tsc hoisted to the workspace root is found and used"; else echo "  FAIL hoisted tsc (got: $out)"; fail=1; fi
  mkdir -p "$tmp/plain/scripts"; printf 'export const s = 1;\n' > "$tmp/plain/scripts/seed.ts"
  out=$(run "$tmp/plain/scripts/seed.ts" "")
  if printf '%s' "$out" | grep -q 'not part of any program'; then echo "  ok   positive: file outside every tsconfig program reported (not a silent pass)"; else echo "  FAIL outside-program file silent (got: $out)"; fail=1; fi
  mkfixture "$tmp/cfg" plain
  if [ -n "${TYPECHECK_SELFTEST_TS:-}" ]; then
    printf '{ "extends": "./tsconfig.base.json", "compilerOptions": { "strict": true, "noEmit": true }, "include": ["src"] }\n' > "$tmp/cfg/tsconfig.json"
  else
    printf '#!/bin/sh\necho "error TS5083: Cannot read file tsconfig.base.json."\nfind src -name "*.ts" | sed "s|^|$(pwd -P)/|"\nexit 1\n' > "$tmp/cfg/node_modules/.bin/tsc"
  fi
  out=$(run "$tmp/cfg/src/app/app.ts" "")
  if printf '%s' "$out" | grep -q 'TS5083'; then echo "  ok   positive: tsconfig error surfaced although the edited file is clean"; else echo "  FAIL config error hidden (got: $out)"; fail=1; fi
  if [ -z "${TYPECHECK_SELFTEST_TS:-}" ]; then
    mkfixture "$tmp/crash" plain; printf '#!/bin/sh\necho "RangeError: Maximum call stack size exceeded"\nexit 134\n' > "$tmp/crash/node_modules/.bin/tsc"
    out=$(run "$tmp/crash/src/app/app.ts" "")
    if printf '%s' "$out" | grep -q 'without diagnostics'; then echo "  ok   positive: tsc crash (exit 134, no diagnostics) reported"; else echo "  FAIL tsc crash hidden (got: $out)"; fail=1; fi
  fi

  # --- Dart: fake dart; error count must work with zero matches (the old arithmetic bug).
  printf 'void main(){}\n' > "$tmp/a.dart"
  mkdir -p "$tmp/d1" "$tmp/d0"
  printf '#!/bin/sh\necho "Analyzing a.dart..."\necho "  error - a.dart:1:1 - Undefined name x - undefined_identifier"\necho "1 issue found."\nexit 3\n' > "$tmp/d1/dart"
  printf '#!/bin/sh\necho "Analyzing a.dart..."\necho "No issues found!"\nexit 0\n' > "$tmp/d0/dart"
  chmod +x "$tmp/d1/dart" "$tmp/d0/dart"
  out=$(run "$tmp/a.dart" "$tmp/d1")
  if printf '%s' "$out" | grep -q "undefined_identifier"; then echo "  ok   positive: dart error reported"; else echo "  FAIL dart positive (got: $out)"; fail=1; fi
  out=$(run "$tmp/a.dart" "$tmp/d0")
  if [ -z "$out" ]; then echo "  ok   negative: dart clean file silent (zero-match path)"; else echo "  FAIL dart negative (got: $out)"; fail=1; fi

  # --- Python: mypy configured vs not configured.
  py="$tmp/py"; mkdir -p "$py/app" "$tmp/m1" "$tmp/m0"
  printf '[tool.mypy]\nstrict = true\n' > "$py/pyproject.toml"; printf 'x: int = "s"\n' > "$py/app/m.py"
  printf '#!/bin/sh\necho "app/m.py:1: error: Incompatible types in assignment  [assignment]"\necho "Found 1 error in 1 file"\nexit 1\n' > "$tmp/m1/mypy"
  printf '#!/bin/sh\necho "Success: no issues found in 1 source file"\nexit 0\n' > "$tmp/m0/mypy"
  chmod +x "$tmp/m1/mypy" "$tmp/m0/mypy"
  out=$(run "$py/app/m.py" "$tmp/m1")
  if printf '%s' "$out" | grep -q "assignment"; then echo "  ok   positive: mypy error reported"; else echo "  FAIL mypy positive (got: $out)"; fail=1; fi
  out=$(run "$py/app/m.py" "$tmp/m0")
  if [ -z "$out" ]; then echo "  ok   negative: mypy clean is silent"; else echo "  FAIL mypy negative (got: $out)"; fail=1; fi
  out=$(run "$py/app/m.py" "")
  if printf '%s' "$out" | grep -q "was NOT type-checked"; then echo "  ok   positive: configured but missing checker is reported"; else echo "  FAIL missing checker hidden (got: $out)"; fail=1; fi
  nocfg="$tmp/nocfg"; mkdir -p "$nocfg"; printf '[project]\nname="x"\n' > "$nocfg/pyproject.toml"; printf 'x: int = "s"\n' > "$nocfg/m.py"
  out=$(run "$nocfg/m.py" "$tmp/m1")
  if [ -z "$out" ]; then echo "  ok   negative: no type checker configured -> silent"; else echo "  FAIL unconfigured project not silent (got: $out)"; fail=1; fi

  printf 'hi\n' > "$tmp/a.txt"
  out=$(run "$tmp/a.txt" "$tmp/m1"); rc=$?
  if [ -z "$out" ] && [ "$rc" -eq 0 ]; then echo "  ok   negative: other file types ignored"; else echo "  FAIL other types"; fail=1; fi
  rm -rf "$tmp"
  if [ "$fail" -eq 0 ]; then echo "selftest PASS"; else echo "selftest FAIL"; fi
  return "$fail"
}

if [ "${1:-}" = "--selftest" ]; then selftest; exit $?; fi
run_hook
exit 0
